import sys

def solve():
    data = sys.stdin.buffer.read().split()
    if not data:
        return

    N = int(data[0])
    A = list(map(int, data[1:]))

    size = N + 1
    bit = [0] * (size + 2)

    def add(idx, val):
        while idx <= size:
            bit[idx] += val
            idx += idx & -idx

    def prefix_sum(idx):
        s = 0
        while idx > 0:
            s += bit[idx]
            idx -= idx & -idx
        return s

    total_adults = 0
    ans = []

    for j in range(1, N + 1):
        expired = prefix_sum(j - 1)
        gifts = total_adults - expired

        stones = A[j - 1] + gifts
        active_until = min(N + 1, j + stones)

        add(active_until, 1)
        total_adults += 1

        ans.append(str(max(0, stones - (N - j))))

    print(" ".join(ans))

if __name__ == "__main__":
    solve()
